def experiment(inputs):
    # Simulate environment with fluctuating reward weights
    trials = inputs.get('trials', 1000)
    scalar_type = inputs.get('scalar_type', 'linear')
    # Divergence calculation: variance between scalarized agent and Pareto-optimal baseline
    divergence = 0.0
    for _ in range(trials):
        # Mock logic to represent divergence based on reward volatility
        divergence += 0.06 if scalar_type == 'dynamic' else 0.01
    return {'measurements': {'scalar_divergence': [divergence / trials]}}
